export function pluralize(count: number, word: string): string {
  return count === 1 ? `1 ${word}` : `${count} ${word}s`;
}

export function pluralize_formatted(count: string, word: string): string {
  const singular_lines = count.split("\n").map(line => line === "1" || line.startsWith("1.") && line.length > 2 && line.split("0").join("") === "1.");
  return singular_lines.includes(true) ? `${count} ${word}` : `${count} ${word}s`;
}
